import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
cur = con.cursor()
print("--- tables whose FKs reference populations ---")
for (name,) in cur.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall():
    for fk in cur.execute(f"PRAGMA foreign_key_list({name})"):
        # fk: id, seq, table, from, to, on_update, on_delete, match
        if fk[2] == 'populations':
            print(f"{name}.{fk[3]} -> populations.{fk[4]}  on_update={fk[5]} on_delete={fk[6]}")
print("\n--- foreign_keys pragma default state ---")
print(cur.execute("PRAGMA foreign_keys").fetchone())
print("\n--- views mentioning populations or MOB or population_code ---")
for (name,sql) in cur.execute("SELECT name, sql FROM sqlite_master WHERE type='view'").fetchall():
    hit = []
    if 'population' in (sql or '').lower(): hit.append('population')
    if 'MOB' in (sql or ''): hit.append('MOB')
    print(f"[{name}] {'MATCH: '+','.join(hit) if hit else 'no match'}")
print("\n--- view SQL for matching views ---")
for (name,sql) in cur.execute("SELECT name, sql FROM sqlite_master WHERE type='view'").fetchall():
    if 'population' in (sql or '').lower() or 'MOB' in (sql or ''):
        print(f"===== {name} =====\n{sql}\n")
print("--- any CHECK constraint mentioning MOB in any table SQL ---")
for (name,sql) in cur.execute("SELECT name, sql FROM sqlite_master WHERE type='table' AND sql LIKE '%MOB%'").fetchall():
    print(name)
print("\n--- indexes on population columns ---")
for (name,sql) in cur.execute("SELECT name, sql FROM sqlite_master WHERE type='index' AND sql LIKE '%population%'").fetchall():
